-- Real local PostgreSQL tests. Fixtures/messages/actions roll back; never reset.
begin;
create function pg_temp.ok(v boolean,msg text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',msg;end if;end$$;
create function pg_temp.denied(q text) returns boolean language plpgsql as $$begin execute q;return false;exception when others then return true;end$$;
do $$
declare a uuid:='a2000000-0000-4000-8000-000000000001';b uuid:='b2000000-0000-4000-8000-000000000002';c uuid:='c2000000-0000-4000-8000-000000000003';client uuid:=gen_random_uuid();r jsonb;snap jsonb;inv uuid;n uuid:=gen_random_uuid();count_before bigint;
begin
 insert into auth.users(id) values(a),(b),(c);
 perform set_config('request.jwt.claim.sub',a::text,true);set local role authenticated;perform public.mmo_connect(client,'Farm Alpha','farm');
 perform set_config('request.jwt.claim.sub',b::text,true);perform public.mmo_connect(client,'Farm Beta','farm');
 perform set_config('request.jwt.claim.sub',c::text,true);perform public.mmo_connect(client,'Farm Gamma','town');
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform pg_temp.ok(pg_temp.denied('select private.mmo_base_api(''state'',''{}'')'),'base dispatcher denied');
 perform pg_temp.ok(pg_temp.denied('insert into private.sf_grants(owner,guest) values(auth.uid(),auth.uid())'),'direct grant writes denied');
 perform pg_temp.ok(pg_temp.denied(format('select public.mmo_farm_state(%L)',b)),'uninvited farm read denied');
 r:=public.mmo_profile_save('I grow carrots','{"appearance":{"shirt":"#224466"},"choice":{"model":"farmer"}}');perform pg_temp.ok(r->>'bio'='I grow carrots' and r->>'friendship'='self','profile save');
 perform pg_temp.ok(pg_temp.denied('select public.mmo_profile_save(repeat(''x'',241),null)'),'long biography denied');
 r:=public.mmo_profile_save(E'First line\nSecond line',null);perform pg_temp.ok(r->>'bio'=E'First line\nSecond line','multiline biography accepted');
 perform public.mmo_friend_action('request',b);
 perform set_config('request.jwt.claim.sub',b::text,true);r:=public.mmo_profile(a);perform pg_temp.ok(r->>'friendship'='incoming','incoming profile');
 perform public.mmo_friend_action('request',a);r:=public.mmo_social_state();perform pg_temp.ok(jsonb_array_length(r->'friends')=0,'cross request never autoaccepts');
 reset role;update private.sf_limits set last_social='-infinity' where user_id=b;
 set local role authenticated;perform public.mmo_friend_action('accept',a);
 r:=public.mmo_profile(a);perform pg_temp.ok(r->>'friendship'='friend' and not(r?'email') and not(r?'inventory'),'safe accepted profile');
 perform set_config('request.jwt.claim.sub',a::text,true);
 snap:='{"farmLayout":{"house":{"x":7,"z":-2,"rotation":0},"portal":{"x":0,"z":12,"rotation":0},"pond":{"x":16,"z":-7,"rotation":0},"trees":{},"buildings":{},"terrain":{},"decorations":{}},"soil":{},"plants":{},"choppedTrees":{},"growth":{"carrotSeconds":1,"treeSeconds":180,"eggSeconds":180},"chickens":[],"farmPausedAt":null}';
 r:=public.mmo_farm_publish(snap);perform pg_temp.ok(r->>'harvested_carrots'='0' and r->'snapshot'->'soil'='{}','initial publish');
 perform pg_temp.ok(pg_temp.denied('select public.mmo_farm_publish(''{}'')'),'invalid snapshot denied');
 perform pg_temp.ok(pg_temp.denied(format('select public.mmo_farm_invite(%L)',c)),'nonfriend invite denied');
 r:=public.mmo_farm_invite(b);inv:=(r->'sent_invitations'->0->>'id')::uuid;
 perform set_config('request.jwt.claim.sub',c::text,true);perform pg_temp.ok(pg_temp.denied(format('select public.mmo_farm_invitation(%L,true)',inv)),'invitation addressed recipient only');
 perform set_config('request.jwt.claim.sub',b::text,true);r:=public.mmo_farm_invitation(inv,true);perform pg_temp.ok(r->>'owner_id'=a::text,'accepted farm snapshot');
 perform public.mmo_connect(client,'Farm Beta','farm:'||a);r:=public.mmo_tick(client,1,3,5);perform pg_temp.ok(r->>'accepted'='false','guest cannot spoof initial position');
 reset role;update private.mmo_players set x=3,z=5,budget=0 where id=b;set local role authenticated;
 r:=public.mmo_farm_state(a,'{"x":999,"z":999,"userId":"spoof","y":1,"yaw":2,"moving":true,"running":false}');
 perform pg_temp.ok((select (p->>'x')::numeric=3 and p->>'userId'=b::text from jsonb_array_elements(r->'occupants') p where p->>'userId'=b::text),'occupants derive validated x and identity');
 perform pg_temp.ok(pg_temp.denied(format('select public.mmo_farm_action(%L,''dig'',''3,5'',gen_random_uuid())',a)),'center tile denied');
 perform pg_temp.ok(pg_temp.denied(format('select public.mmo_farm_action(%L,''dig'',''20,20'',gen_random_uuid())',a)),'remote action denied');
 r:=public.mmo_farm_action(a,'dig','4,5',n);perform pg_temp.ok(r->'snapshot'->'soil'?'4,5','shared digging');
 r:=public.mmo_farm_action(a,'dig','4,5',n);perform pg_temp.ok(r->'snapshot'->'soil'?'4,5','idempotent retry');
 perform pg_temp.ok(pg_temp.denied(format('select public.mmo_farm_action(%L,''plant'',''4,5'',%L)',a,n)),'nonce cannot change action');
 perform public.mmo_farm_action(a,'plant','4,5',gen_random_uuid());r:=public.mmo_farm_action(a,'water','4,5',gen_random_uuid());
 perform pg_temp.ok(jsonb_typeof(r->'snapshot'->'plants'->'4,5'->'wateredAt')='number','millisecond crop clock');
 perform pg_temp.ok(pg_temp.denied(format('select public.mmo_farm_action(%L,''harvest'',''4,5'',gen_random_uuid())',a)),'premature harvest denied');
 reset role;
 -- Use an explicit text-array path because commas are legal tile-key contents.
 update private.sf_farms set data=jsonb_set(data,array['plants','4,5','wateredAt'],to_jsonb(floor(extract(epoch from clock_timestamp()-interval '2 seconds')*1000))) where owner=a;
 set local role authenticated;r:=public.mmo_farm_state(a);perform pg_temp.ok(r->'snapshot'->'plants'->'4,5'->>'stage'='2' and r->'snapshot'->'plants'->'4,5'->>'watered'='false','server stage advances once then needs water');
 perform public.mmo_farm_action(a,'water','4,5',gen_random_uuid());
 reset role;update private.sf_farms set data=jsonb_set(data,array['plants','4,5','wateredAt'],to_jsonb(floor(extract(epoch from clock_timestamp()-interval '2 seconds')*1000))) where owner=a;
 set local role authenticated;n:=gen_random_uuid();r:=public.mmo_farm_action(a,'harvest','4,5',n);perform pg_temp.ok(r->>'harvested_carrots'='1' and not(r->'snapshot'->'plants'?'4,5'),'owner harvest receipt');
 r:=public.mmo_farm_action(a,'harvest','4,5',n);perform pg_temp.ok(r->>'harvested_carrots'='1','retry no duplicate reward');
 perform pg_temp.ok(pg_temp.denied(format('select public.mmo_farm_action(%L,''restore'',''4,5'',gen_random_uuid())',a)),'visitor restore denied');
 perform set_config('request.jwt.claim.sub',a::text,true);r:=public.mmo_farm_publish(snap-'soil'-'plants');perform pg_temp.ok(r->'snapshot'->'soil'?'4,5' and r->>'harvested_carrots'='1','later publish preserves shared soil and receipts');
 perform public.mmo_tick(client,1,3,5);perform public.mmo_farm_action(a,'plant','4,5',gen_random_uuid());perform public.mmo_farm_action(a,'water','4,5',gen_random_uuid());
 r:=public.mmo_farm_publish(jsonb_set(snap,'{farmPausedAt}',to_jsonb(floor(extract(epoch from clock_timestamp())*1000))));
 perform set_config('request.jwt.claim.sub',b::text,true);perform pg_temp.ok(pg_temp.denied(format('select public.mmo_farm_action(%L,''dig'',''4,6'',gen_random_uuid())',a)),'paused actions denied');
 reset role;update private.sf_farms set data=jsonb_set(data,'{farmPausedAt}',to_jsonb(floor(extract(epoch from clock_timestamp()-interval '10 seconds')*1000))) where owner=a;
 perform set_config('request.jwt.claim.sub',a::text,true);set local role authenticated;r:=public.mmo_farm_publish(snap);perform pg_temp.ok(r->'snapshot'->'plants'->'4,5'->>'stage'='1' and(r->'snapshot'->'plants'->'4,5'->>'wateredAt')::numeric>extract(epoch from clock_timestamp())*1000,'resume shifts crop clock');
 reset role;update private.sf_farms set data=jsonb_set(data,array['plants','4,5','wateredAt'],'null') where owner=a;
 set local role authenticated;r:=public.mmo_farm_action(a,'restore','4,5',gen_random_uuid());
 perform pg_temp.ok(not(r->'snapshot'->'soil'?'4,5') and not(r->'snapshot'->'plants'?'4,5') and r->>'harvested_carrots'='1','owner restore removes immature crop and soil without reward');
 perform pg_temp.ok(pg_temp.denied(format('select public.mmo_farm_action(%L,''restore'',''4,5'',gen_random_uuid())',a)),'restore empty ground rejected');
 perform set_config('request.jwt.claim.sub',b::text,true);perform public.mmo_send('local','shared farm hello',gen_random_uuid());
 perform set_config('request.jwt.claim.sub',a::text,true);r:=public.mmo_history('local');perform pg_temp.ok(jsonb_array_length(r)=1,'shared local communication');
 reset role;insert into private.sf_farms(owner,data) values(b,snap);insert into private.sf_grants(owner,guest) values(b,a);insert into private.sf_invites(owner,target) values(b,a);
 perform set_config('request.jwt.claim.sub',b::text,true);set local role authenticated;perform public.mmo_farm_leave(a);
 reset role;perform pg_temp.ok(exists(select 1 from private.sf_grants where owner=b and guest=a) and exists(select 1 from private.sf_invites where owner=b and target=a),'leave preserves reverse-direction invitation and grant');
 insert into private.sf_grants(owner,guest) values(a,b);update private.mmo_players set world_id='farm:'||a,seen=clock_timestamp() where id=b;
 perform set_config('request.jwt.claim.sub',a::text,true);set local role authenticated;
 perform public.mmo_farm_revoke(b);
 perform set_config('request.jwt.claim.sub',b::text,true);perform pg_temp.ok(pg_temp.denied(format('select public.mmo_farm_state(%L)',a)),'revoked state denied');
 perform pg_temp.ok(pg_temp.denied(format('select public.mmo_connect(gen_random_uuid(),''B'',''farm:%s'')',a)),'revoked connect denied');
 perform pg_temp.ok(pg_temp.denied(format('select public.mmo_farm_action(%L,''dig'',''4,6'',gen_random_uuid())',a)),'revoked action denied');
 reset role;update private.sf_invites set expires_at=clock_timestamp()-interval '1 second' where owner=a and target=b;
 perform set_config('request.jwt.claim.sub',a::text,true);set local role authenticated;r:=public.mmo_farm_invite(b);inv:=(r->'sent_invitations'->0->>'id')::uuid;
 reset role;update private.sf_invites set expires_at=clock_timestamp()-interval '1 second' where id=inv;
 perform set_config('request.jwt.claim.sub',b::text,true);set local role authenticated;perform pg_temp.ok(pg_temp.denied(format('select public.mmo_farm_invitation(%L,true)',inv)),'expired invitation denied');
 reset role;delete from private.sf_invites where id=inv;insert into private.sf_grants(owner,guest) values(a,b);update private.sf_limits set last_social='-infinity' where user_id=a;
 perform set_config('request.jwt.claim.sub',b::text,true);set local role authenticated;perform public.mmo_connect(client,'Farm Beta','farm:'||a);
 perform set_config('request.jwt.claim.sub',a::text,true);perform public.mmo_friend_action('remove',b);
 perform set_config('request.jwt.claim.sub',b::text,true);perform pg_temp.ok(pg_temp.denied(format('select public.mmo_farm_state(%L)',a)),'unfriend revokes grants');
 reset role;
 -- Expired grants deny all live communication and movement in the foreign scope.
 insert into private.sf_friends values(least(a,b),greatest(a,b));insert into private.sf_grants(owner,guest,expires_at) values(a,b,clock_timestamp()-interval '1 second');
 update private.mmo_players set world_id='farm:'||a,seen=clock_timestamp() where id=b;
 perform set_config('request.jwt.claim.sub',b::text,true);set local role authenticated;
 perform pg_temp.ok(pg_temp.denied(format('select public.mmo_tick(%L,2,3,5)',client)),'expired grant tick denied');
 perform pg_temp.ok(pg_temp.denied('select public.mmo_send(''local'',''expired'',gen_random_uuid())'),'expired grant local send denied');
 perform pg_temp.ok(pg_temp.denied('select public.mmo_history(''world'')'),'expired grant world history denied');
 reset role;update private.sf_grants set expires_at=clock_timestamp()+interval '1 hour' where owner=a and guest=b;update private.mmo_players set social_at='-infinity' where id=a;
 perform set_config('request.jwt.claim.sub',a::text,true);set local role authenticated;perform public.mmo_social('block','party',b);
 perform set_config('request.jwt.claim.sub',b::text,true);perform pg_temp.ok(pg_temp.denied(format('select public.mmo_farm_state(%L)',a)),'blocking revokes grants');
 reset role;
 raise notice 'PASS: social/farm profiles, friend acceptance, visits, scope, shared crops, receipts, pause/resume, expiry and revocation';
end$$;
rollback;
begin;
create function pg_temp.ok(v boolean,msg text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',msg;end if;end$$;
-- Separate backend sessions race the shared farm row and access locks.
-- Extension installation is rolled back; remote fixture commits are cleaned below.
create extension if not exists dblink with schema extensions;
do $$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();c uuid:=gen_random_uuid();cfg text:='host=127.0.0.1 port=5432 dbname=postgres user=postgres password=postgres';d jsonb;r record;successes int:=0;counter int;waiting boolean:=false;cleanup text;
begin
 if not(select rolsuper from pg_roles where rolname=current_user) then raise notice 'SKIP: run this SQL as local supabase_admin to exercise separate-session races';return;end if;
 cleanup:=format('delete from auth.users where id in(%L,%L,%L);delete from realtime.messages where topic in(%L,%L,%L)',a,b,c,'mmo:inbox:'||a,'mmo:inbox:'||b,'mmo:inbox:'||c);
 perform extensions.dblink_connect('sf_setup',cfg);
 d:='{"farmLayout":{"house":{"x":7,"z":-2,"rotation":0},"portal":{"x":0,"z":12,"rotation":0},"pond":null,"trees":{},"buildings":{},"terrain":{},"decorations":{}},"soil":{"4,5":{"watered":false}},"plants":{"4,5":{"stage":3,"watered":false,"wateredAt":null}},"choppedTrees":{},"growth":{"carrotSeconds":1,"treeSeconds":180,"eggSeconds":180},"chickens":[],"farmPausedAt":null}';
 perform extensions.dblink_exec('sf_setup',format('insert into auth.users(id) values(%L),(%L),(%L);insert into private.mmo_players(id,name,client,world_id,x,z,seen) values(%L,''Race Host'',gen_random_uuid(),%L,3,5,clock_timestamp()),(%L,''Race Guest B'',gen_random_uuid(),%L,3,5,clock_timestamp()),(%L,''Race Guest C'',gen_random_uuid(),%L,3,5,clock_timestamp());insert into private.sf_friends values(least(%L::uuid,%L::uuid),greatest(%L::uuid,%L::uuid)),(least(%L::uuid,%L::uuid),greatest(%L::uuid,%L::uuid));insert into private.sf_farms(owner,data) values(%L,%L);insert into private.sf_grants(owner,guest) values(%L,%L),(%L,%L)',a,b,c,a,'farm:'||a,b,'farm:'||a,c,'farm:'||a,a,b,a,b,a,c,a,c,a,d,a,b,a,c));
 perform extensions.dblink_connect('sf_one',cfg);perform extensions.dblink_connect('sf_two',cfg);perform extensions.dblink_connect('sf_three',cfg);
 perform extensions.dblink_exec('sf_one',format('set role authenticated;set request.jwt.claim.sub=%L',b));
 perform extensions.dblink_exec('sf_two',format('set role authenticated;set request.jwt.claim.sub=%L',c));
 perform extensions.dblink_send_query('sf_one',format('select public.mmo_farm_action(%L,''harvest'',''4,5'',gen_random_uuid())',a));
 perform extensions.dblink_send_query('sf_two',format('select public.mmo_farm_action(%L,''harvest'',''4,5'',gen_random_uuid())',a));
 for r in select result from extensions.dblink_get_result('sf_one',false) as x(result jsonb) loop successes:=successes+1;end loop;
 for r in select result from extensions.dblink_get_result('sf_two',false) as x(result jsonb) loop successes:=successes+1;end loop;
 perform pg_temp.ok(successes=1,'concurrent harvest has one winner');
 for r in select n from extensions.dblink('sf_setup',format('select harvested_carrots from private.sf_farms where owner=%L',a)) as x(n bigint) loop perform pg_temp.ok(r.n=1,'concurrent harvest credits once');end loop;
 perform * from extensions.dblink_get_result('sf_one',false) as x(result jsonb);
 perform * from extensions.dblink_get_result('sf_two',false) as x(result jsonb);
 perform extensions.dblink_exec('sf_one','reset role;begin');
 perform * from extensions.dblink('sf_one','select pg_advisory_xact_lock_shared(hashtextextended(''sf-access'',0))') as x(v text);
 perform extensions.dblink_exec('sf_two',format('set request.jwt.claim.sub=%L;set application_name=''sf-revoke-race''',a));
 perform extensions.dblink_send_query('sf_two',format('select public.mmo_farm_revoke(%L)',b));
 for counter in 1..100 loop
  select exists(select 1 from pg_stat_activity where application_name='sf-revoke-race' and wait_event_type='Lock') into waiting;
  exit when waiting;perform pg_sleep(.02);
 end loop;
 perform pg_temp.ok(waiting,'revoke actually waits for active read lock');
 perform extensions.dblink_exec('sf_three',format('set role authenticated;set request.jwt.claim.sub=%L',b));
 perform extensions.dblink_send_query('sf_three',format('select public.mmo_farm_state(%L)',a));
 perform extensions.dblink_exec('sf_one','commit');
 perform * from extensions.dblink_get_result('sf_two',true) as x(result jsonb);
 successes:=0;for r in select result from extensions.dblink_get_result('sf_three',false) as x(result jsonb) loop successes:=successes+1;end loop;
 perform pg_temp.ok(successes=0,'queued read cannot survive committed revocation');
 perform extensions.dblink_disconnect('sf_one');perform extensions.dblink_disconnect('sf_two');perform extensions.dblink_disconnect('sf_three');
 perform extensions.dblink_exec('sf_setup',cleanup);perform extensions.dblink_disconnect('sf_setup');
 raise notice 'PASS: separate-session harvest race credits once; queued farm read denied after revocation';
exception when others then
 begin perform extensions.dblink_disconnect('sf_one');exception when others then null;end;
 begin perform extensions.dblink_disconnect('sf_two');exception when others then null;end;
 begin perform extensions.dblink_disconnect('sf_three');exception when others then null;end;
 begin perform extensions.dblink_exec('sf_setup',cleanup);perform extensions.dblink_disconnect('sf_setup');exception when others then null;end;
 raise;
end$$;
rollback;
